package com.sarc.backend.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="partes_medicos",uniqueConstraints=@UniqueConstraint(columnNames="cita_id")) public class ParteMedico { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) private Cita cita; @ManyToOne(optional=false) private Usuario medico; private String diagnostico,tratamiento,observaciones; private LocalDateTime emitidoEn; public Long getId(){return id;} public Cita getCita(){return cita;} public void setCita(Cita v){cita=v;} public Usuario getMedico(){return medico;} public void setMedico(Usuario v){medico=v;} public String getDiagnostico(){return diagnostico;} public void setDiagnostico(String v){diagnostico=v;} public String getTratamiento(){return tratamiento;} public void setTratamiento(String v){tratamiento=v;} public String getObservaciones(){return observaciones;} public void setObservaciones(String v){observaciones=v;} public LocalDateTime getEmitidoEn(){return emitidoEn;} public void setEmitidoEn(LocalDateTime v){emitidoEn=v;} }
